package com.aicommerce.platform.delivery.application.port;
import java.util.*; import com.aicommerce.platform.delivery.domain.PlatformObservedState;
public record ReconciliationFound(Optional<String> externalId,Optional<String> safeProviderTraceId,Optional<PlatformObservedState> observedState,NormalizedPlatformEvidence evidence) implements PlatformReconciliationOutcome{public ReconciliationFound{externalId=PlatformContractSupport.opt(externalId);safeProviderTraceId=PlatformContractSupport.opt(safeProviderTraceId);observedState=PlatformContractSupport.opt(observedState);PlatformContractSupport.req(evidence);externalId.ifPresent(PlatformContractSupport::safe);safeProviderTraceId.ifPresent(PlatformContractSupport::safe);if(evidence.attemptKind()!=com.aicommerce.platform.delivery.domain.PlatformAttemptKind.RECONCILE||evidence.resultKind()!=com.aicommerce.platform.delivery.domain.PlatformEvidenceResultKind.FOUND||!evidence.observedState().equals(observedState))throw PlatformContractSupport.invalid();}}
